/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const unconfirmedUserGroups = helpers.translateSync('Unconfirmed user groups');
    const incompatibleUsers = helpers.translateSync('Incompatible users');
    const unmappedGlobalCustomTables = helpers.translateSync('Unmapped global custom tables');
    const unmappedCustomApplications = helpers.translateSync('Unmapped custom applications');
    const tabs = api.state.unconfirmed_user_flow_enabled ? [{
        "id": "t0",
        "label": unconfirmedUserGroups
    }] : [];
    tabs.push({
        "id": "t1",
        "label": unmappedGlobalCustomTables
    }, {
        "id": "t2",
        "label": unmappedCustomApplications
    });
    return tabs;
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  const issuesTabID = api.state.issuesTabID;
  //enable reference links only on Unconfirmed user groups and Incompatible users tabs
  switch(issuesTabID) {
    case 't0':
      return false;
    case 't1':
      return true;
    case 't2':
      return true;
    case 't3':
      return false;  
    default:
      return true;
  }
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const unconfirmedUserGroups = helpers.translateSync('Unconfirmed user groups');
    const incompatibleUsers = helpers.translateSync('Incompatible users');
    const unmappedGlobalCustomTables = helpers.translateSync('Unmapped global custom tables');
    const unmappedCustomApplications = helpers.translateSync('Unmapped custom applications');
    const issuesTabID = api.state.issuesTabID;
    switch (issuesTabID) {
        case 't0':
            return unconfirmedUserGroups;
        case 't1':
            return unmappedGlobalCustomTables;
        case 't2':
            return unmappedCustomApplications;
        case 't3':
            return incompatibleUsers;
        default:
            return unmappedGlobalCustomTables;
    }
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	const issuesTabID = api.state.issuesTabID;
	switch(issuesTabID) {
    case 't0':
      return 'sn_sub_man_unallocated_group_recommendation';
    case 't1':
      return 'global_custom_tables_recommendation';
    case 't2':
      return 'custom_applications_recommendation';
    case 't3':
      return 'unallocated_user_recommendation';  
    default:
      return 'global_custom_tables_recommendation';
  }
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
    const issuesTabID = api.state.issuesTabID;
    switch(issuesTabID) {
    case 't1':
      return helpers.translateSync('Map the global custom tables to these products?');
    case 't2':
      return helpers.translateSync('Map the custom applications to these products?');
    default:
      return helpers.translateSync('Map the global custom tables to these products?');
  }
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  const issuesTabID = api.state.issuesTabID;
  switch(issuesTabID) {
    case 't1':
      return 'table_name,recommendation_product';
    case 't2':
      return 'name,recommendation_product';
    default:
      return 'table_name,recommendation_product';
  }
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  const idList = api.state.selectedRecommendationRecords.toString();
	return 'sys_idIN' + idList;
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
    const issuesTabID = api.state.issuesTabID;
    switch(issuesTabID) {
    case 't1':
      return helpers.translateSync('Selected global custom tables');
    case 't2':
      return helpers.translateSync('Selected custom applications');
    default:
      return helpers.translateSync('Selected global custom tables');
  }
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	const issuesTabID = api.state.issuesTabID;
	switch(issuesTabID) {
    case 't1':
      return 'global_custom_tables_recommendation';
    case 't2':
      return 'custom_applications_recommendation';
    default:
      return 'global_custom_tables_recommendation';
  }
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    const issuesTabID = api.state.issuesTabID;
    let eventName;

    switch (issuesTabID) {
        case 't1':
            eventName = 'Map global custom table to subscription';
            break;
        case 't2':
            eventName = 'Map custom app to subscription';
            break;
        default:
            eventName = null;
    }

    if (eventName) {
        return {
            event: eventName,
            value: {}
        };
    }
}
